// woocommerce_check_cart_items runs on the cart page and again when the order is submitted.
add_action( 'woocommerce_check_cart_items', 'perfectpixel_minimum_order_amount' );

function perfectpixel_minimum_order_amount() {
	if ( ! WC()->cart || WC()->cart->is_empty() ) {
		return;
	}
	$minimum = (float) '{{minimum_amount}}';
	$current = (float) WC()->cart->get_subtotal() + ( WC()->cart->display_prices_including_tax() ? (float) WC()->cart->get_subtotal_tax() : 0 );

	if ( $minimum > 0 && $current < $minimum ) {
		wc_add_notice(
			sprintf( esc_html( '{{minimum_message}}' ), wc_price( $minimum ), wc_price( $current ) ),
			'error'
		);
	}
}
